150|/***
151| * MARK: ensureCompileCache
152| * @description Defaults `NODE_COMPILE_CACHE` (persisted V8 compilation output
153| *   the many vitest workers share) and creates the directory, matching the
154| *   old shell gate. Children inherit it through `spawn` env. The default is
155| *   disk-backed (`~/.cache`): /tmp is tmpfs (RAM) on the gate host and the
156| *   cache grows to ~1G, which directly eats memory and swap (2026-11-03).
157| * @example ensureCompileCache() => process.env.NODE_COMPILE_CACHE is set
158| ***/
159|function ensureCompileCache() {
160|	if (!process.env.NODE_COMPILE_CACHE) {
161|		process.env.NODE_COMPILE_CACHE = path.join(os.homedir(), ".cache", "kainbain-compile-cache");
162|	}
163|	fs.mkdirSync(process.env.NODE_COMPILE_CACHE, { recursive: true });
164|}
