166|/***
167| * MARK: bashAvailable
168| * @description Whether `bash` resolves on PATH (needed only by the
169| *   bash-only security-scan harness branch).
170| * @example bashAvailable() => true
171| * @returns {boolean}
172| ***/
173|function bashAvailable() {
174|	try {
175|		const result = spawnSync("bash", ["--version"], { stdio: "ignore", windowsHide: true });
176|		return !result.error;
177|	} catch {
178|		return false;
179|	}
180|}
181|
182|/***
183| * MARK: dockerAvailable
184| * @description Whether a Docker daemon is reachable (needed only by the
185| *   Container Tests branch, which builds and boots the production image).
186| * @example dockerAvailable() => true
187| * @returns {boolean}
188| ***/
189|function dockerAvailable() {
190|	try {
191|		const result = spawnSync("docker", ["info"], { stdio: "ignore", windowsHide: true });
192|		return !result.error && result.status === 0;
193|	} catch {
194|		return false;
195|	}
196|}
