198|/***
199| * MARK: depcheckAvailable
200| * @description Whether the `depcheck` devDependency binary is installed in
201| *   the root tree (needed only by the Dependency Check branch). A pure file
202| *   probe — no spawn, no network — so it stays fast and offline-safe; a
203| *   production-only (`--omit=dev`) provisioning simply reports false and
204| *   the gate SKIPs the branch instead of failing it.
205| * @example depcheckAvailable() => true
206| * @param {Object} [opts]
207| * @param {string} [opts.root] - repo root to probe, defaults to the gate's root.
208| * @param {string} [opts.targetPlatform] - defaults to process.platform.
209| * @returns {boolean}
210| ***/
211|export function depcheckAvailable({ root = REPO_ROOT, targetPlatform = process.platform } = {}) {
212|	const bin = targetPlatform === "win32" ? "depcheck.cmd" : "depcheck";
213|	try {
214|		return fs.existsSync(path.join(root, "node_modules", ".bin", bin));
215|	} catch {
216|		return false;
217|	}
218|}
