243|export function workspaceDepsInstalled({ root = REPO_ROOT, packages = WORKSPACE_PACKAGES } = {}) {
244|	const missing = {};
245|	for (const pkg of packages) {
246|		let dependencies = null;
247|		try {
248|			const manifest = JSON.parse(
249|				fs.readFileSync(path.join(root, pkg, "package.json"), "utf8"),
250|			);
251|			dependencies = { ...(manifest.dependencies || {}), ...(manifest.devDependencies || {}) };
252|		} catch {
253|			missing[pkg] = [`${pkg}/package.json unreadable`];
