255|		}
256|		const absent = Object.keys(dependencies).filter((name) => {
257|			try {
258|				return !fs.existsSync(path.join(root, pkg, "node_modules", name, "package.json"));
259|			} catch {
260|				return true;
261|			}
262|		});
