292|export function ensureWorkspaceDeps({ root = REPO_ROOT, withCanary = true, npmExec = NPM, spawnFn = spawnSync } = {}) {
293|	const packages = withCanary
294|		? [...WORKSPACE_PACKAGES]
295|		: WORKSPACE_PACKAGES.filter((name) => name !== "canary-e2e");
296|	const before = workspaceDepsInstalled({ root, packages });
297|	if (before.installed) return { ok: true, installed: [] };
298|	const installed = [];
299|	for (const pkg of Object.keys(before.missing)) {
300|		if (before.missing[pkg].length === 1 && before.missing[pkg][0].endsWith("package.json unreadable")) {
301|			return { ok: false, error: `Workspace dependencies could not be checked (${before.missing[pkg][0]}).` };
302|		}
303|		console.log(
304|			`Dependencies missing for ${pkg} (${before.missing[pkg].join(", ")}) — installing (npm install --prefix ${pkg})...`,
305|		);
306|		let status = null;
307|		let spawnError = null;
308|		try {
309|			const result = spawnFn(npmExec, ["install", "--prefix", pkg], {
310|				cwd: root,
311|				timeout: WORKSPACE_INSTALL_TIMEOUT_MS,
312|				stdio: "inherit",
313|			});
314|			status = result?.status ?? null;
315|			spawnError = result?.error ?? null;
316|		} catch (err) {
317|			spawnError = err;
318|		}
319|		if (spawnError != null || (typeof status === "number" && status !== 0)) {
320|			const cause =
321|				spawnError != null
322|					? `install failed: ${spawnError.message || String(spawnError)}`
323|					: `install exited with status ${status}`;
324|			return {
325|				ok: false,
326|				error: `Workspace dependencies could not be installed for ${pkg} (${cause}). Refusing to run a gate whose branches would fail for missing setup.`,
327|			};
328|		}
329|		installed.push(pkg);
330|	}
331|	const after = workspaceDepsInstalled({ root, packages });
332|	if (after.installed) {
333|		console.log(`Workspace dependencies installed (${installed.join(", ")}).`);
334|		return { ok: true, installed };
335|	}
336|	const stillMissing = Object.entries(after.missing)
337|		.map(([pkg, names]) => `${pkg}: ${names.join(", ")}`)
338|		.join("; ");
339|	return {
340|		ok: false,
341|		error: `Workspace dependencies installed but still missing (${stillMissing}). Refusing to run a gate whose branches would fail for missing setup.`,
342|	};
