292|export function ensureWorkspaceDeps({ root = REPO_ROOT, withCanary = true, npmExec = NPM, spawnFn = spawnSync } = {}) {
293|	const packages = withCanary
294|		? [...WORKSPACE_PACKAGES]
295|		: WORKSPACE_PACKAGES.filter((name) => name !== "canary-e2e");
296|	const before = workspaceDepsInstalled({ root, packages });
297|	if (before.installed) return { ok: true, installed: [] };
298|	const installed = [];
