302|		}
303|		console.log(
304|			`Dependencies missing for ${pkg} (${before.missing[pkg].join(", ")}) — installing (npm install --prefix ${pkg})...`,
305|		);
306|		let status = null;
307|		let spawnError = null;
308|		try {
309|			const result = spawnFn(npmExec, ["install", "--prefix", pkg], {
