  /***
   * MARK: closeCreateProjectModal
   * @description Closes the "Create New Project" dialog and clears its error.
   * @example closeCreateProjectModal()
   ***/
  const closeCreateProjectModal = () => {
    setIsCreatingProject(false);
    setCreateError('');
  };

  /***
   * MARK: switchToAdoptProjectModal
   * @description Swaps the creation dialog for the adoption dialog (the
   *   local-only path for users with no git remote yet).
   * @example switchToAdoptProjectModal()
   ***/
  const switchToAdoptProjectModal = () => {
    setIsCreatingProject(false);
    setCreateError('');
    setIsRegisteringProject(true);
  };

  /***
   * MARK: handleCreateProjectSubmit
   * @description Handles form submission for creating a new project,
   *   forwarding the optional git remote URL (D11). A rejected creation
   *   surfaces the server message inline and keeps the dialog open.
   * @example handleCreateProjectSubmit(event)
   * @param {React.FormEvent} e
   ***/
  const handleCreateProjectSubmit = async (e) => {
    e.preventDefault();
    if (!newProjName.trim()) return;
    setCreateError('');
    try {
      // Advanced: a blank docs-repo URL means the default (docs inside the
      // main repo); a set URL moves all KainBain docs/state into the
      // separate repo. undefined keys are dropped by JSON.stringify.
      const docsRepoUrl = newProjDocsRepoUrl.trim();
      await createProject(newProjName.trim(), {
        gitUrl: newProjGitUrl.trim() || undefined,
        ...(docsRepoUrl ? { docsRepo: { url: docsRepoUrl } } : {}),
      });
      setNewProjName('');
      setNewProjGitUrl('');
      setNewProjDocsRepoUrl('');
      setCreateAdvancedOpen(true);
      setIsCreatingProject(false);
      setIsProjectDropdownOpen(false);
    } catch (err) {
      // The server's own sentence (e.g. a docsRepo 400/409), not the
      // transport wrapper — the dialog stays open with the fix inline.
      setCreateError(serverErrorMessage(err, 'Failed to create the project.'));
    }
  };

  /***
   * MARK: closeAdoptProjectModal
   * @description Closes the "Add Existing Project" dialog and clears its error.
   * @example closeAdoptProjectModal()
   ***/
  const closeAdoptProjectModal = () => {
    setIsRegisteringProject(false);
    setAdoptError('');
  };

  /***
   * MARK: handleAdoptProjectSubmit
   * @description Handles form submission for adopting an existing project
   *   directory: POSTs `/projects/register` through the context action, then
   *   closes the dialog. A rejected registration surfaces the server message
   *   inline instead of throwing out of the form.
   * @example handleAdoptProjectSubmit(event)
   * @param {React.FormEvent} e
   ***/
  const handleAdoptProjectSubmit = async (e) => {
    e.preventDefault();
    const path = adoptPath.trim();
    if (!path) return;
    if (typeof registerProject !== 'function') return;
    setAdoptError('');
    try {
      // Advanced: a blank docs-repo URL means the default (docs inside the
      // main repo); a set URL moves all KainBain docs/state into the
      // separate repo, optionally at an explicit local checkout path.
      const docsRepoUrl = adoptDocsRepoUrl.trim();
      const docsRepoPath = adoptDocsRepoPath.trim();
      await registerProject({
        path,
        // JSON.stringify drops undefined keys, so an omitted name / state
        // folder never reaches the API (which would reject a blank string).
        name: adoptName.trim() || undefined,
        kainbainDirName: adoptKainbainDir.trim() || undefined,
        ...(docsRepoUrl
